    b_merged = merge_intervals(b)

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current = a_start
        for b_start, b_end in b_merged:
            if b_end <= current:
                # b interval is entirely before current position
                continue
            if b_start >= a_end:
                # b interval is entirely after remaining a
                break
            if b_start > current:
                # Add the part before b_start
                result.append([current, b_start])
            # Move current past b_end
            current = max(current, b_end)

        # Add any remaining part of a interval
        if current < a_end:
            result.append([current, a_end])

    return result


def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals by start point
    sorted_intervals = sorted(intervals)

    merged = [sorted_intervals[0]]
    for current_start, current_end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]

        if current_start <= last_end:
            # Overlapping or touching intervals - merge them
            merged[-1] = [last_start, max(last_end, current_end)]
        else:
            # Non-overlapping interval
            merged.append([current_start, current_end])

    return merged

